*{box-sizing:border-box} :root{--ink:#f4f3ec;--muted:#a3aaa7;--lime:#d8f36a;--panel:rgba(17,24,25,.82);--line:rgba(255,255,255,.14)} html,body{margin:0;min-height:100%;background:#101619;color:var(--ink);font-family:Manrope,system-ui,sans-serif}body{display:grid;place-items:center;padding:20px;overflow:hidden}.game-shell{width:min(1440px,100%);height:min(900px,calc(100dvh - 40px));min-height:560px;display:grid;grid-template-rows:68px minmax(0,1fr) 42px;background:#171e20;border:1px solid rgba(255,255,255,.1);box-shadow:0 28px 90px #0008;overflow:hidden}.topbar{display:flex;align-items:center;padding:0 28px;background:#131a1c;border-bottom:1px solid rgba(255,255,255,.07);z-index:2}.brand{display:flex;align-items:center;gap:11px;color:inherit;text-decoration:none}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid #d8f36a;border-radius:9px;color:#d8f36a;font-weight:800;font-size:15px;letter-spacing:-3px;padding-right:3px}.brand-mark span{font-size:10px;align-self:start;margin:5px 0 0 -7px}.brand-name{font-size:12px;letter-spacing:.18em;font-weight:800;line-height:1.05}.brand-name span{display:block;color:#9da6a2;font-size:8px;letter-spacing:.33em;margin-top:3px}.session-pill{margin-left:43px;display:flex;align-items:center;gap:9px;color:#bdc4bf;font:10px 'DM Mono',monospace;letter-spacing:.08em}.live-dot,.online-dot{width:7px;height:7px;background:#d8f36a;border-radius:50%;box-shadow:0 0 12px #d8f36a99}.session-pill i{height:13px;border-left:1px solid #49504e;margin:0 4px}.top-actions{margin-left:auto;display:flex;align-items:center;gap:10px}.weather{display:flex;align-items:center;gap:8px;margin-right:11px;color:#aab1ae;font:9px 'DM Mono',monospace;letter-spacing:.08em}.weather b{color:#f4f3ec;font-weight:500}.sun{color:#f0c77b;font-size:18px}.icon-btn{height:31px;width:34px;background:#202829;border:1px solid #343d3d;border-radius:6px;color:#dce1dc;font-size:17px;cursor:pointer}.icon-btn:hover{color:var(--lime);border-color:#a6be57}.game-stage{position:relative;min-height:0;overflow:hidden;background:#485150}#gameCanvas{position:absolute;inset:0;width:100%;height:100%;display:block}.stage-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(7,12,13,.44),transparent 40%,transparent 80%,rgba(7,12,13,.08)),linear-gradient(0deg,rgba(6,10,11,.4),transparent 28%,transparent 85%,rgba(6,10,11,.12)}.glass{background:var(--panel);border:1px solid rgba(255,255,255,.13);box-shadow:0 12px 35px #0003;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}.mission-card{position:absolute;left:28px;top:27px;width:280px;padding:21px 21px 17px;border-radius:11px}.eyebrow{display:flex;align-items:center;gap:8px;color:#c5d2b0;font:9px 'DM Mono',monospace;letter-spacing:.14em}.eyebrow-line{width:16px;border-top:1px solid var(--lime)}.mission-number{margin-left:auto;color:#7f8984}.mission-card h1,.start-panel h2,.complete-panel h2{margin:17px 0 10px;font-size:36px;line-height:1.08;letter-spacing:-.055em;font-weight:700}.mission-card h1 em,.start-panel h2 em,.complete-panel h2 em{font-family:Georgia,serif;font-weight:400;color:var(--lime);letter-spacing:-.045em}.mission-card>p{margin:0;color:#aeb6b1;font-size:11px;line-height:1.6;max-width:225px}.objective{height:53px;margin-top:19px;padding:0 10px;display:flex;align-items:center;gap:10px;background:rgba(216,243,106,.08);border:1px solid rgba(216,243,106,.24);border-radius:7px}.target-icon{font-size:21px;color:var(--lime)}.objective div{display:grid;gap:3px}.objective small,.mission-stats small{font:8px 'DM Mono',monospace;color:#89938d;letter-spacing:.12em}.objective strong{font-size:11px;font-weight:700}.objective strong span{color:var(--lime);margin:0 3px}.target-arrow{margin-left:auto;color:var(--lime);font-size:15px}.mission-stats{display:flex;justify-content:space-between;margin-top:17px;padding-top:14px;border-top:1px solid #ffffff17}.mission-stats div{display:grid;gap:6px}.mission-stats strong{font:12px 'DM Mono',monospace;font-weight:500}.top-right-hud{position:absolute;right:26px;top:24px;display:flex;align-items:flex-start;gap:9px}.minimap-card{width:208px;padding:10px 10px 8px;border-radius:9px}.mini-head{display:flex;justify-content:space-between;color:#c3ccc5;font:8px 'DM Mono',monospace;letter-spacing:.11em}.mini-north{color:#8e9992}#miniMap{display:block;width:100%;height:115px;margin-top:6px;border-radius:3px}.mini-legend{display:flex;gap:12px;color:#aab2ad;font:7px 'DM Mono',monospace;letter-spacing:.08em}.mini-legend span{display:flex;align-items:center;gap:5px}.you-dot,.goal-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#f4f3ec}.goal-dot{background:var(--lime);box-shadow:0 0 7px var(--lime)}.gear-card{width:61px;height:96px;border-radius:9px;display:flex;align-items:center;flex-direction:column;justify-content:center;gap:2px}.gear-label,.gear-caption{font:8px 'DM Mono',monospace;color:#909b95;letter-spacing:.12em}.gear-card strong{font:31px 'DM Mono',monospace;color:var(--lime);line-height:1.2}.bottom-hud{position:absolute;left:28px;right:28px;bottom:24px;display:flex;align-items:flex-end;justify-content:space-between}.speed-card{width:156px;border-radius:9px;padding:11px 13px 10px}.speed-top{display:flex;justify-content:space-between;color:#a9b1ac;font:8px 'DM Mono',monospace;letter-spacing:.12em}.speed-readout{display:flex;align-items:baseline;gap:6px;margin:2px 0 6px}.speed-readout strong{font:32px 'DM Mono',monospace;letter-spacing:-.07em}.speed-unit{color:#909b95;font:8px 'DM Mono',monospace}.speed-track,.progress-track{height:3px;background:#ffffff20;border-radius:9px;overflow:hidden}.speed-track i,.progress-track i{height:100%;width:0;display:block;background:var(--lime);transition:width .15s}.center-hint{padding:9px 13px;border-radius:8px;display:flex;align-items:center;gap:5px;color:#aab4ae;font:8px 'DM Mono',monospace;letter-spacing:.1em}.hint-key{display:inline-grid;place-items:center;width:18px;height:18px;border:1px solid #ffffff3a;border-radius:4px;color:#f0f3eb;font-size:9px}.center-hint>span:last-child{margin-left:7px}.parking-progress{width:190px;border-radius:9px;padding:11px;display:flex;align-items:center;gap:10px}.progress-icon{font-size:20px;color:var(--lime)}.parking-progress>div{flex:1}.parking-progress small{font:7px 'DM Mono',monospace;color:#a0aaa4;letter-spacing:.12em}.parking-progress strong{display:block;font:10px 'DM Mono',monospace;letter-spacing:.05em;margin:4px 0 7px}.progress-track{height:2px}.progress-track i{transition:width .1s}.start-overlay,.complete-overlay{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center;background:rgba(9,14,15,.2);transition:opacity .35s,visibility .35s}.start-overlay.hidden,.complete-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-panel,.complete-panel{width:390px;padding:29px 32px 21px;border-radius:13px;background:rgba(15,22,23,.9);box-shadow:0 26px 90px #0008}.start-kicker{display:flex;align-items:center;gap:8px;color:#c7d0c8;font:9px 'DM Mono',monospace;letter-spacing:.13em}.start-kicker .live-dot{width:6px;height:6px}.start-panel h2,.complete-panel h2{font-size:48px;margin:21px 0 11px}.start-panel>p,.complete-panel>p{color:#aab3ae;font-size:12px;line-height:1.7;max-width:295px;margin:0 0 22px}.start-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:47px;padding:0 16px;border:0;border-radius:6px;background:var(--lime);color:#18201a;font:800 10px Manrope,sans-serif;letter-spacing:.1em;cursor:pointer;transition:transform .18s,background .18s}.start-button:hover{transform:translateY(-2px);background:#e5ff86}.start-button b{font-size:19px;font-weight:500}.start-controls{margin-top:16px;display:flex;align-items:center;gap:7px;color:#89938d;font:7px 'DM Mono',monospace;letter-spacing:.08em}.start-controls span:first-child{color:#c6cdc7}.control-divider{color:#66716b}.complete-overlay{z-index:5;background:rgba(9,14,15,.5)}.complete-panel{width:330px;text-align:center;padding:22px 29px}.complete-panel .eyebrow{justify-content:center;margin-top:6px}.complete-panel h2{font-size:45px;margin:12px 0}.complete-panel>p{margin:0 auto 15px}.complete-star{font-size:25px;color:var(--lime)}.result-score{display:flex;align-items:center;justify-content:space-between;padding:11px 2px;border-top:1px solid #ffffff1f;border-bottom:1px solid #ffffff1f;margin-bottom:16px;color:#aab3ae;font:9px 'DM Mono',monospace;letter-spacing:.1em}.result-score strong{font-size:17px;color:var(--lime)}.toast{position:absolute;left:50%;top:24px;transform:translate(-50%,-10px);opacity:0;transition:.22s;background:rgba(14,20,20,.9);border:1px solid #ffffff25;border-radius:7px;padding:10px 15px;color:#f0f3eb;font:10px 'DM Mono',monospace;letter-spacing:.05em;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.damage-flash{position:absolute;inset:0;pointer-events:none;background:rgba(255,95,67,0);transition:background .1s}.damage-flash.hit{background:rgba(255,95,67,.2)}.footer{height:42px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;background:#131a1c;color:#8f9993;font:8px 'DM Mono',monospace;letter-spacing:.12em}.footer>div{display:flex;align-items:center;gap:8px}.footer-mark{display:grid;place-items:center;width:17px;height:17px;border:1px solid #aeb995;border-radius:4px;color:var(--lime);font:700 8px Manrope;letter-spacing:-1px}.footer-center{gap:10px}.footer-center i{height:12px;border-left:1px solid #434c47}.footer>div:last-child{color:#bec6bf}.online-dot{width:5px;height:5px}.touch-controls{display:none;position:absolute;z-index:3;left:20px;right:20px;bottom:18px;align-items:end;justify-content:space-between;pointer-events:none}.steer-pad,.pedals{display:flex;gap:9px;pointer-events:auto}.steer-pad button,.pedal{width:56px;height:56px;border-radius:50%;border:1px solid #ffffff4a;color:#fff;background:#111a1acc;backdrop-filter:blur(8px);font-size:27px;touch-action:none;user-select:none}.steer-pad button:active,.pedal:active{background:#d8f36a;color:#101619}.pedals{align-items:flex-end}.pedal{font:8px 'DM Mono',monospace;letter-spacing:.06em}.pedal.drive{height:70px;width:59px;background:#d8f36ac9;color:#172019;border-color:#e6ff99}.pedal.brake{height:48px;width:48px;font-size:7px}.pedal.reverse{height:53px;width:49px}.paused-overlay{position:absolute;inset:0;z-index:4;background:#091011aa;display:grid;place-items:center;color:#fff}
@media(max-width:850px){body{padding:0;overflow:hidden}.game-shell{width:100%;height:100dvh;min-height:0;border:0;grid-template-rows:54px minmax(0,1fr) 30px}.topbar{padding:0 14px}.brand-mark{width:29px;height:29px}.session-pill{margin-left:19px;font-size:8px}.weather{display:none}.mission-card{left:14px;top:14px;width:225px;padding:14px}.mission-card h1{font-size:28px;margin:12px 0 7px}.mission-card>p{font-size:9px}.objective{margin-top:11px;height:45px}.mission-stats{margin-top:11px;padding-top:9px}.top-right-hud{right:13px;top:13px}.minimap-card{width:160px;padding:8px}.gear-card{width:48px;height:78px}.gear-card strong{font-size:26px}#miniMap{height:86px}.bottom-hud{left:14px;right:14px;bottom:13px}.speed-card{width:129px;padding:8px 10px}.speed-readout strong{font-size:26px}.parking-progress{width:165px;padding:9px}.center-hint{display:none}.footer{height:30px;padding:0 13px;font-size:7px}.touch-controls{display:flex}.start-panel{width:min(370px,calc(100% - 34px));padding:25px 24px 18px}.start-panel h2{font-size:43px}.start-panel>p{font-size:11px}.start-overlay{background:rgba(9,14,15,.42)}.bottom-hud{bottom:94px}.mission-card{max-width:calc(100% - 195px)}.top-right-hud .minimap-card{width:145px}.top-right-hud .gear-card{display:none}}
@media(max-width:530px){.topbar{height:50px}.session-pill{margin-left:auto;margin-right:auto;font-size:7px;gap:6px}.top-actions{gap:5px}.icon-btn{width:29px;height:29px}.brand-name{font-size:10px}.brand-name span{font-size:7px}.mission-card{width:173px;max-width:calc(100% - 175px);padding:11px;top:10px;left:10px}.mission-card h1{font-size:23px;margin:9px 0 6px}.mission-card>p{font-size:8px;line-height:1.45}.mission-number{display:none}.objective{padding:0 6px;gap:6px;height:40px}.objective small{font-size:7px}.objective strong{font-size:9px}.target-icon{font-size:17px}.target-arrow{display:none}.mission-stats{gap:6px}.mission-stats small{font-size:6px}.mission-stats strong{font-size:10px}.top-right-hud{top:10px;right:9px}.top-right-hud .minimap-card{width:127px;padding:7px}.mini-head{font-size:7px}#miniMap{height:70px;margin-top:4px}.mini-legend{font-size:6px;gap:6px}.bottom-hud{left:10px;right:10px;bottom:83px;align-items:end}.speed-card{width:110px;padding:7px}.speed-top{font-size:7px}.speed-readout strong{font-size:23px}.parking-progress{width:147px;padding:8px;gap:7px}.parking-progress small{font-size:6px}.parking-progress strong{font-size:8px}.progress-icon{font-size:16px}.touch-controls{left:12px;right:12px;bottom:13px}.steer-pad,.pedals{gap:6px}.steer-pad button{height:48px;width:48px}.pedal{width:45px;height:48px}.pedal.drive{height:60px;width:51px}.pedal.brake{height:41px;width:41px}.footer{font-size:6px;padding:0 9px}.footer-center{gap:6px}.footer-mark{width:14px;height:14px}.start-panel{padding:20px 21px 15px}.start-kicker{font-size:8px}.start-panel h2{font-size:40px;margin:16px 0 8px}.start-panel>p{font-size:10px;margin-bottom:15px}.start-controls{font-size:6px;gap:5px}.complete-panel{width:min(320px,calc(100% - 30px))}}
@media(max-height:650px) and (min-width:851px){body{padding:8px}.game-shell{height:calc(100dvh - 16px);min-height:0;grid-template-rows:52px minmax(0,1fr) 32px}.mission-card{top:14px;padding:15px;width:250px}.mission-card h1{font-size:30px;margin:12px 0 8px}.mission-card>p{font-size:10px}.objective{margin-top:12px}.mission-stats{margin-top:10px;padding-top:10px}.bottom-hud{bottom:13px}.footer{height:32px}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('miniMap');
  const mctx = mapCanvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const W = 1800, H = 1200;
  const target = { x: 1370, y: 354, angle: Math.PI / 2 };
  const playerStart = { x: 385, y: 856, angle: -0.07 };
  const keys = new Set();
  const touch = { left: false, right: false, forward: false, reverse: false, brake: false };
  let cars = [], camera = { x: playerStart.x, y: playerStart.y }, player, started = false, complete = false;
  let elapsed = 0, impacts = 0, parkProgress = 0, lastFrame = 0, toastTimer = 0, audioCtx = null, soundOn = true;
  let viewW = 0, viewH = 0, dpr = 1, elapsedDisplay = -1;
  const colors = ['#d8e5e3', '#d2b279', '#718b8a', '#b95f4c', '#9ca7b1', '#596a5c', '#d5d4c8'];
  const targetBay = { x: target.x - 42, y: target.y - 66, w: 84, h: 132 };
  const roadLines = [];
  for (let x = 56; x < W; x += 74) roadLines.push(x);

  function buildCars() {
    cars = [];
    const xs = [294, 399, 504, 609, 714, 819, 924, 1029, 1134, 1239, 1344, 1449, 1554];
    xs.forEach((x, i) => {
      if (Math.abs(x - target.x) < 52) return;
      if (![4, 8, 11].includes(i)) cars.push({ x, y: 345 + (i % 3) * 5, angle: -Math.PI / 2, color: colors[(i + 2) % colors.length], parked: true });
    });
    xs.forEach((x, i) => {
      if (![1, 5, 9].includes(i)) cars.push({ x: x + (i % 2 ? 10 : 0), y: 936 - (i % 3) * 4, angle: -Math.PI / 2, color: colors[(i + 4) % colors.length], parked: true });
    });
    cars.push({ x: 175, y: 592, angle: 0, color: '#b8c2bd', parked: true });
    cars.push({ x: 1680, y: 720, angle: Math.PI, color: '#c0a287', parked: true });
  }
  function freshPlayer() { return { x: playerStart.x, y: playerStart.y, angle: playerStart.angle, speed: 0, steer: 0, moving: false }; }
  buildCars(); player = freshPlayer();

  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    viewW = Math.max(1, rect.width); viewH = Math.max(1, rect.height);
    canvas.width = Math.round(viewW * dpr); canvas.height = Math.round(viewH * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener('resize', resize); resize();

  function roundedRect(c, x, y, w, h, r) {
    c.beginPath(); c.roundRect(x, y, w, h, r);
  }
  function drawWorld() {
    ctx.fillStyle = '#555c59'; ctx.fillRect(0, 0, W, H);
    // Asphalt tonal variation and subtle aggregate flecks.
    ctx.fillStyle = '#545b59'; ctx.fillRect(0, 145, W, 1055);
    for (let i = 0; i < 250; i++) {
      const x = (i * 197 + 51) % W, y = 160 + ((i * 311 + 93) % 1025);
      ctx.fillStyle = i % 3 ? 'rgba(227,230,216,.025)' : 'rgba(16,23,23,.06)';
      ctx.fillRect(x, y, 2 + i % 3, 1 + i % 2);
    }
    // Arrival boulevard and parking aisles.
    ctx.fillStyle = '#4d5552'; ctx.fillRect(0, 520, W, 235);
    ctx.fillStyle = '#606763'; ctx.fillRect(0, 624, W, 2);
    ctx.setLineDash([25, 22]); ctx.strokeStyle = 'rgba(220,225,209,.36)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(30, 641); ctx.lineTo(W - 30, 641); ctx.stroke(); ctx.setLineDash([]);
    // Mall façade at the far edge.
    ctx.fillStyle = '#414846'; ctx.fillRect(0, 0, W, 144);
    ctx.fillStyle = '#737a73'; ctx.fillRect(0, 139, W, 12);
    ctx.fillStyle = '#303838'; ctx.fillRect(0, 16, W, 9);
    for (let x = 28; x < W - 20; x += 128) {
      ctx.fillStyle = '#687674'; ctx.fillRect(x, 35, 92, 82);
      ctx.fillStyle = '#8d9b91'; ctx.fillRect(x + 4, 39, 84, 3);
      ctx.fillStyle = '#43504f'; ctx.fillRect(x + 4, 45, 84, 65);
      ctx.fillStyle = 'rgba(197,218,202,.13)'; ctx.fillRect(x + 10, 50, 29, 55);
      ctx.fillStyle = '#7b837a'; ctx.fillRect(x + 44, 44, 2, 67);
    }
    // Concrete curbs, islands, shrubs.
    drawIsland(92, 450, 155, 32); drawIsland(1578, 790, 142, 31);
    drawIsland(1045, 510, 142, 25); drawIsland(475, 762, 145, 24);
    // Parking space paint.
    const stalls = [294,399,504,609,714,819,924,1029,1134,1239,1344,1449,1554];
    for (const x of stalls) {
      // Top row, deliberately leave target bay open.
      ctx.strokeStyle = 'rgba(223,225,207,.68)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(x - 48, 278); ctx.lineTo(x - 48, 433); ctx.moveTo(x + 48, 278); ctx.lineTo(x + 48, 433); ctx.stroke();
      // Bottom row.
      ctx.beginPath(); ctx.moveTo(x - 48, 807); ctx.lineTo(x - 48, 1000); ctx.moveTo(x + 48, 807); ctx.lineTo(x + 48, 1000); ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(230,235,216,.7)'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(245, 278); ctx.lineTo(1598, 278); ctx.moveTo(245, 433); ctx.lineTo(1598, 433);
    ctx.moveTo(245, 807); ctx.lineTo(1598, 807); ctx.moveTo(245, 1000); ctx.lineTo(1598, 1000); ctx.stroke();
    // Disabled / accessible bay marks.
    ctx.strokeStyle = 'rgba(114,180,185,.68)'; ctx.lineWidth = 2;
    ctx.strokeRect(250, 278, 88, 155); ctx.strokeRect(250, 807, 88, 193);
    drawAccessibleSymbol(294, 350); drawAccessibleSymbol(294, 902);
    // The destination bay with pulsing guide marks.
    const pulse = .68 + Math.sin(performance.now() * .004) * .17;
    ctx.fillStyle = `rgba(216,243,106,${started ? .17 : .11})`;
    roundedRect(ctx, targetBay.x, targetBay.y, targetBay.w, targetBay.h, 7); ctx.fill();
    ctx.strokeStyle = `rgba(216,243,106,${pulse})`; ctx.lineWidth = 3; ctx.setLineDash([9, 6]);
    ctx.strokeRect(targetBay.x + 2, targetBay.y + 2, targetBay.w - 4, targetBay.h - 4); ctx.setLineDash([]);
    ctx.fillStyle = '#d8f36a'; ctx.font = '500 16px "DM Mono", monospace'; ctx.textAlign = 'center'; ctx.fillText('24', target.x, target.y - 76);
    // Direction arrows in driving lanes.
    ctx.fillStyle = 'rgba(225,229,212,.35)';
    for (let x = 170; x < 1660; x += 225) {
      ctx.beginPath(); ctx.moveTo(x, 580); ctx.lineTo(x - 10, 595); ctx.lineTo(x - 3, 595); ctx.lineTo(x - 3, 611); ctx.lineTo(x + 3, 611); ctx.lineTo(x + 3, 595); ctx.lineTo(x + 10, 595); ctx.closePath(); ctx.fill();
    }
    // Entrance markings.
    ctx.fillStyle = 'rgba(231,231,211,.55)'; ctx.font = '500 12px "DM Mono",monospace'; ctx.textAlign = 'left'; ctx.fillText('SLOW  •  PARKING ZONE', 52, 555);
    // Boundaries are decorative, not barriers.
    ctx.strokeStyle = 'rgba(205,210,194,.21)'; ctx.lineWidth = 3; ctx.strokeRect(20, 162, W - 40, 1020);
    drawCars(); drawPlayer();
  }
  function drawIsland(x, y, w, h) {
    ctx.fillStyle = '#737872'; roundedRect(ctx, x - 5, y - 4, w + 10, h + 8, h / 2); ctx.fill();
    ctx.fillStyle = '#3e5548'; roundedRect(ctx, x, y, w, h, h / 2); ctx.fill();
    for (let i = 0; i < Math.floor(w / 23); i++) {
      ctx.fillStyle = i % 2 ? '#718267' : '#82906f';
      ctx.beginPath(); ctx.arc(x + 12 + i * 22, y + h / 2 + Math.sin(i * 3) * 3, 7 + (i % 2), 0, Math.PI * 2); ctx.fill();
    }
  }
